function isValidUrl(raw){ try{ var u=new URL(normalizeUrl(raw)); return u.hostname.indexOf('.')>0 && !/\s/.test(u.hostname); }catch(e){ return false; } }
function fetchMeta(url){
  var host = hostOf(url);
  if(/unreachable|\.invalid|broken/i.test(url)){
    return { failed:true, title:'', description:'', host:host, iconLetter:host.charAt(0).toUpperCase(), color:'#94a3b8' };
  }
  var seg='';
  try{ seg = decodeURIComponent(new URL(normalizeUrl(url)).pathname.split('/').filter(Boolean).pop()||''); }catch(e){}
  seg = seg.replace(/[-_]+/g,' ').replace(/\.\w+$/,'').trim();
  var pretty = seg ? seg.replace(/\b\w/g, function(c){return c.toUpperCase();}) : host;
  var siteName = host.split('.')[0].replace(/\b\w/g,function(c){return c.toUpperCase();});
  return {
    title: seg ? (pretty + ' · ' + siteName) : (siteName + ' — homepage'),
    description: 'A page on ' + host + '. This description is what the app pulled from the page so you can recognise it later.',
    host: host,
    iconLetter: host.charAt(0).toUpperCase(),
    color: colorFor(host)
  };
}

