  list.innerHTML='';
  if(items.length===0){ count.textContent=''; var d=document.createElement('div'); d.className='empty'; d.textContent='Nothing saved yet. Paste a link above to get started.'; list.appendChild(d); return; }
  var q=query.trim();
  var compiled=buildQuery(q); highlights=compiled.literals;
  function inView(it){
    if(statusFilter==='archived') return it.archived;
