function openCompose(url){
  var meta=fetchMeta(url);
  var slot=document.getElementById('composeSlot');
  slot.innerHTML='';
  var card=document.createElement('div'); card.className='card';
  var head=document.createElement('div'); head.className='compose-head';
  head.textContent = meta.failed
    ? "We couldn't load this page's details automatically — you can still save it and add a title yourself."
    : 'We pulled these details from the page — adjust anything before saving:';
  if(meta.failed) head.style.color='#b46a00';
  var preview=document.createElement('div'); preview.className='preview';
  var thumb=document.createElement('div'); thumb.className='thumb'; thumb.style.background = meta.failed ? '#e6e8eb' : ('linear-gradient(135deg,'+meta.color+',#0d1b3a)');
  if(meta.failed){ thumb.style.color='#6b7684'; thumb.textContent='No preview'; } else { thumb.textContent=meta.host; }
  var right=document.createElement('div'); right.style.flex='1'; right.style.minWidth='0';
  var f1=field('Title','input',meta.title), f2=field('Description','textarea',meta.description), cf=toReadToggle(false), tf=tagEditor([]), nf=field('Notes (Markdown supported)','textarea','');
  if(meta.failed){ f1.querySelector('input').placeholder='Give this bookmark a title'; }
  var alink=document.createElement('a'); alink.className='link'; alink.href=normalizeUrl(url); alink.target='_blank'; alink.rel='noopener'; alink.textContent=normalizeUrl(url); alink.style.marginTop='0';
  right.appendChild(f1); right.appendChild(f2); right.appendChild(cf); right.appendChild(tf); right.appendChild(nf); right.appendChild(alink);
  preview.appendChild(thumb); preview.appendChild(right);
  var actions=document.createElement('div'); actions.style.display='flex'; actions.style.gap='8px'; actions.style.marginTop='14px';
  var add=document.createElement('button'); add.className='btn'; add.textContent='Add to bookmarks';
  var cancel=document.createElement('button'); cancel.className='btn secondary'; cancel.textContent='Cancel';
  add.onclick=function(){
    items.unshift({ id:Date.now(), url:normalizeUrl(url), title:f1.querySelector('input').value.trim()||(meta.failed?normalizeUrl(url):meta.title),
      description:f2.querySelector('textarea').value.trim(), host:meta.host, iconLetter:meta.iconLetter, color:meta.color,
      toRead:cf.querySelector('.choice').getAttribute('data-value')==='1', archived:false, tags:tf.getTags(),
      notes:nf.querySelector('textarea').value, saved:'just now', _new:true });
    slot.innerHTML=''; render();
  };
  cancel.onclick=function(){ slot.innerHTML=''; };
  actions.appendChild(add); actions.appendChild(cancel);
  card.appendChild(head); card.appendChild(preview); card.appendChild(actions);
  slot.appendChild(card);
}

