function hostOf(u){ try{ return new URL(normalizeUrl(u)).hostname.replace(/^www\./,''); }catch(e){ return u; } }
function keyOf(u){ // duplicate detection: host is case-insensitive (ignore www + trailing slash),
  try{ var x=new URL(normalizeUrl(u)); // but the path keeps its original capitalisation.
    var host=x.hostname.replace(/^www\./,'').toLowerCase();
    var path=(x.pathname+ (x.search||'')).replace(/\/$/,'');
    return host+path; }
  catch(e){ return u; }
}

